  METERS: [['effort','Nỗ lực trí óc','#ff6b81'],['speed','Tốc độ nói','#4fc3f7'],['accuracy','Độ chính xác','#66d9a8'],['auto','Tự động (không cần nghĩ)','#ffd166'],['myelin','Myelin trên dây cáp','#f1faee'],['vocab','Số từ đã lưu','#c792ea']],
